/// The fixed-size portion of one little-endian record.
pub(super) struct RecordHeader {
    pub(super) sequential_id: u32,
    pub(super) network_hash: u32,
    pub(super) raw_flags: u8,
    pub(super) model_family: u8,
    pub(super) contributor_role: u8,
    pub(super) model_mask: u8,
    pub(super) face_coverage: u8,
    pub(super) confidence: u8,
    pub(super) raw_provenance: u8,
    pub(super) box_count: u8,
    pub(super) shape_id: u16,
    pub(super) name_len: u16,
    pub(super) state_len: u32,
    pub(super) values: [u32; 8],
    pub(super) beacon_tint: u8,
    pub(super) raw_traits: u64,
    pub(super) survival: u8,
}

/// Read the fixed header in schema order before validating its facts.
pub(super) fn read_record_header(
    reader: &mut Reader<'_>,
    previous: bool,
) -> Result<RecordHeader, AssetError> {
    Ok(RecordHeader {
        sequential_id: reader.read_u32("record sequential_id")?,
        network_hash: reader.read_u32("record network_hash")?,
        raw_flags: reader.read_u8("record raw_flags")?,
        model_family: reader.read_u8("record model_family")?,
        contributor_role: reader.read_u8("record contributor_role")?,
        model_mask: reader.read_u8("record model_mask")?,
        face_coverage: reader.read_u8("record face_coverage")?,
        confidence: reader.read_u8("record confidence")?,
        raw_provenance: reader.read_u8("record raw_provenance")?,
        box_count: reader.read_u8("record box_count")?,
        shape_id: reader.read_u16("record shape_id")?,
        name_len: reader.read_u16("record name_len")?,
        state_len: reader.read_u32("record state_len")?,
        values: {
            let mut values = [0; 8];
            for value in &mut values {
                *value = reader.read_u32("record values")?;
            }
            values
        },
        beacon_tint: if previous {
            0
        } else {
            reader.read_u8("record beacon_tint")?
        },
        raw_traits: if previous {
            0
        } else {
            reader.read_u64("record raw_traits")?
        },
        survival: if previous {
            0
        } else {
            reader.read_u8("record survival")?
        },
    })
}
